// #93: bundle docs/releases/X.Y.Z.md deterministically into plugin/_generated/release-notes.ts
// at build time. Pure Node fs/promises so scripts/plugin-build.mjs and Deno tests both import it.
import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

const FINAL_MD_RE = /^(\d+)\.(\d+)\.(\d+)\.md$/;

function compareDesc(a, b) {
  if (a.major !== b.major) return b.major - a.major;
  if (a.minor !== b.minor) return b.minor - a.minor;
  return b.patch - a.patch;
}

/** Read every X.Y.Z.md file in `dir`, sorted newest-first with normalized LF endings. */
export async function readReleaseNotesDir(dir) {
  let names;
  try {
    names = await readdir(dir);
  } catch {
    return [];
  }
  const parsed = [];
  for (const name of names) {
    const m = FINAL_MD_RE.exec(name);
    if (!m) continue;
    parsed.push({
      name,
      version: `${m[1]}.${m[2]}.${m[3]}`,
      major: Number(m[1]),
      minor: Number(m[2]),
      patch: Number(m[3]),
    });
  }
  parsed.sort(compareDesc);
  const out = [];
  for (const item of parsed) {
    const raw = await readFile(path.join(dir, item.name), "utf8");
    const body = raw.replace(/\r\n/g, "\n").trim();
    if (body) out.push({ version: item.version, body });
  }
  return out;
}

/** Generate deterministic TypeScript source for plugin/_generated/release-notes.ts. */
export function generateReleaseNotesModule(entries) {
  const json = JSON.stringify(entries, null, 2);
  return `// AUTO-GENERATED by scripts/plugin-build.mjs. Do not edit.
import type { BundledReleaseNote } from "../ui/release-check-logic.ts";

export const RELEASE_NOTES: readonly BundledReleaseNote[] = ${json};
`;
}
